# cost-recommendation на открытии, внутренний источник там обезличен.


def _input_field_label(field: str) -> str:
    """Подпись поля ВНЕ его группы: у поля объекта — с именем объекта.

    Короткая подпись («Стартовая цена») однозначна только внутри своей группы;
    в окне класса, в строках отклонений и в «Не подставлено» две такие строки
    стояли рядом неразличимыми. Имя объекта — его группа из реестра.
    """
    for group, fields in FIELD_GROUPS:
        for item in fields:
            if item[0] == field:
                title = str(item[1])
                return (f"{title} — {group}" if field in FIELD_SECTIONS
                        else title)
    return field


# Единица измерения поля берётся из той же подписи, что и его имя: второй
# список «что в чём меряется» разошёлся бы с первым молча. Профиль класса был
# весь в тыс ₽, и единицы в таблице классов не было вовсе; с нормативом площади
# на человека рядом со ставкой метра бесподписное 5 читается как ставка — ровно
# та ошибка, что уже ловилась в удельных показателях и на осях графиков.
#
# Берётся ПЕРВАЯ часть подсказки: дальше в ней идёт объяснение, а не мера.
# Считается это здесь и один раз — страница получает готовую карту
# подстановкой, иначе тот же разрез жил бы второй реализацией на JS.
CLASS_FIELD_UNITS_PLACEHOLDER = "__DEVELOPAID_CLASS_UNITS__"
FIELD_UNITS_PLACEHOLDER = "__DEVELOPAID_FIELD_UNITS__"
_CLASS_UNIT_SEPARATORS = (";", " — ", ", ", ": ")
# Пояснение после единицы пишется отдельным предложением: «м²/чел. Сколько…».
# Конец предложения — точка перед заглавной буквой; точка сокращения внутри
# единицы («тыс. ₽») под это не подходит, а у сокращения в конце единицы
# («чел.», «шт.», «мес.») точка остаётся при ней.
_UNIT_SENTENCE_END = re.compile(r"\.\s+(?=[А-ЯЁA-Z«])")
_UNIT_ABBREVIATION_END = re.compile(r"(?:чел|шт|мес|п\.п)$")


def class_field_unit(field: str) -> str:
    """→ единица поля из FIELD_GROUPS («м²/чел.», «тыс. ₽/шт.») или пустое."""
    hint = ""
    for group in FIELD_GROUPS:
        for one in group[1]:
            if one[0] == field:
                hint = str(one[2] or "") if len(one) > 2 else ""
    if not hint:
        return ""
    cut = len(hint)
    for separator in _CLASS_UNIT_SEPARATORS:
        at = hint.find(separator)
        if 0 < at < cut:
            cut = at
    sentence = _UNIT_SENTENCE_END.search(hint)
    if sentence and 0 < sentence.start() < cut:
        cut = sentence.start()
        if _UNIT_ABBREVIATION_END.search(hint[:cut]):
            cut += 1
    return hint[:cut].strip()


def field_units() -> dict[str, str]:
    """Единицы всех полей вводных — для сводки в заголовке группы."""
    fields = [str(one[0]) for group in FIELD_GROUPS for one in group[1]]
    return {field: unit for field in fields if (unit := class_field_unit(field))}


def class_field_units() -> dict[str, str]:
    """Единицы полей профиля класса — то, что подставляется на страницу."""
    fields: list[str] = []
    for preset in PROJECT_CLASS_PRESETS.values():
        for field in preset:
            if field != "label" and field not in fields:
                fields.append(field)
    return {field: class_field_unit(field) for field in fields
            if class_field_unit(field)}


def project_class_deviations(inputs: dict[str, Any]) -> dict[str, Any]:
    """Отклонения ставок проекта от базы выбранного класса.

    База классов одна и общая (решение владельца, 24.08.2026): проект,
    ушедший от неё — правкой руками или личной перекрышкой, — обязан об
    этом говорить в каждой поверхности, иначе два отчёта на «одном классе»
    разойдутся, и оба будут выглядеть достоверно. Список полей класса
    читается из самого пресета: копию списка негде обновлять, потому что
    копии нет — поле, добавленное в пресет, попадает в сверку само.
    """
    key = str((inputs or {}).get("project_class") or "")
    # База — для региона проекта: в МО цена нежилого без московского пола.
    preset = class_base_preset(key, class_region(inputs), project_kind(inputs))
    if not preset:
        return {"class": key, "label": "Пользовательский", "rows": []}
    rows: list[dict[str, Any]] = []
    for field, base in preset.items():
        if field == "label" or not isinstance(base, (int, float)):
            continue
        raw = (inputs or {}).get(field)
        if raw in (None, ""):
            continue
        try:
            actual = float(raw)
        except (TypeError, ValueError):
            continue
        if abs(actual - float(base)) > 1e-9:
            rows.append({
                "field": field,
                "label": _input_field_label(field),
                "unit": class_field_unit(field),
                "base": float(base),
                "actual": actual,
            })
    return {"class": key, "label": str(preset.get("label") or key), "rows": rows}


def project_class_view(inputs: dict[str, Any]) -> dict[str, Any]:
    """Класс проекта — одно решение для карточки «Ключевые параметры», PDF и бота.

    У гостиничного проекта класс — звёздность (поле `hotel_stars` блока
    «Гостиница»), а не класс жилья: пресет жилья — цены квартир, СМР, двор —
    у гостиницы ничего не считает, и «Комфорт» в её отчёте был бы чужой
    предпосылкой. Незаданная звёздность называется «не задан», а не «без
    звёзд». У остальных проектов — класс жилья и его отклонения от базы
    (`project_class_deviations`).
    """
    if is_hotel(inputs or {}):
        stars = (inputs or {}).get(hotel_strategy.PREFIX + "stars")
        return {"kind": "hotel", "title": "Класс гостиницы",
                "class": "" if stars is None else str(stars),
                "label": hotel_strategy.class_label(stars) or "не задан", "rows": []}
    return {"kind": "housing", "title": "Класс проекта", **project_class_deviations(inputs)}


