# Экземпляры объекта. Проект держит столько офисов, ТЦ и наземных паркингов,
# сколько нужно (владелец, 28.09.2026: «возможность добавлять дубли — хоть 2,
# хоть 5 объектов»); ФОК не дублируется (`duplicable`). Прежде вторые объекты были тремя зашитыми
# строками реестра: третий офис или второй ФОК завести было нельзя.
#
# Экземпляр — копия своего типа с номером: `offices3`, `retail3_*`. Имена
# `offices2`, `standalone_retail2`, `above_parking2` — те же, что носили
# «вторые» объекты, поэтому сохранённые проекты открываются без перевода
# ключей. Какие экземпляры ЕСТЬ в проекте, говорит явный список вводной
# `object_instances` (`project_object_instances`), а не угадывание по полям.
#
# Предел — `OBJECT_INSTANCES_MAX` на тип, первый экземпляр включительно. Это
# предел реестра: каждый экземпляр — строка ТЭП, группа вводных и блок книги,
# и поля заводятся заранее. Шестой офис не обрезается молча — добавление
# отказывает и называет предел (`object_instance_refusal`).
OBJECT_INSTANCES_MAX = 5


def object_instance(base: StandaloneObject, number: int) -> StandaloneObject:
    """Экземпляр `number` (со второго) объекта типа `base`."""
    prefix = f"{base.prefix}{number}"

    def own(key: str) -> str:
        # Поле типа всегда начинается с его приставки — иначе экземпляр
        # унаследовал бы ЧУЖОЕ поле, и две вводные стали бы одной.
        if not key.startswith(base.prefix + "_"):
            raise ValueError(f"поле «{key}» не принадлежит типу «{base.key}»")
        return prefix + key[len(base.prefix):]

    return base._replace(
        key=f"{base.key}{number}", prefix=prefix, label=f"{base.label} {number}",
        rate_cost=own(base.rate_cost), rate_price=own(base.rate_price),
        sale_gate=own(base.sale_gate) if base.sale_gate else "",
        tep_label=f"{base.tep_label} {number}",
        group_label=f"{base.group_label} {number}",
        # Блок книги — у двойника типа (ФОК берёт блок ТЦ), продукт — сам тип.
        book_twin=base.book_twin or base.key, family=base.key)


# Реестр — типы и их экземпляры; экземпляр стоит сразу за своим типом:
# порядок реестра — порядок строк ТЭП и групп вводных.
STANDALONE_OBJECTS: tuple[StandaloneObject, ...] = tuple(
    obj for base in OBJECT_TYPES
    for obj in (base, *(object_instance(base, number)
                        for number in range(2, OBJECT_INSTANCES_MAX + 1)
                        if base.duplicable)))


# Вводные объекта порождаются его строкой реестра, а не пишутся руками.
# Умолчаний у объекта 17–20, и на четырёх объектах это 76 полей литералом:
# «поставить пару ОСЗ» означало вписать ещё 72 — то есть завести пятый,
# шестой и седьмой список там, где состав объявлен один раз. Форма при этом
# регулярна и проверена на всех четырёх: общие поля одинаковы, различаются
# ровно те, что уже стоят в реестре (срок, рост, мера), да собственные числа
# объекта.
_OBJECT_SHARED_DEFAULTS: dict[str, Any] = {
    "enabled": False,
    "start": "2028-07-01",
    "sales_start": "2028-07-01",
    "residual_months": 6,
    "share_before_rve_pct": 85,
    "sales_profile": "",
    "growth_stage1_pct": 0,
    "growth_stage2_pct": 0,
    "growth_stage3_pct": 0,
    "growth_stage4_pct": 0,
}


def standalone_object_defaults(obj: StandaloneObject) -> dict[str, Any]:
    """Умолчания одного объекта: общая форма плюс его собственные числа."""
    out: dict[str, Any] = dict(_OBJECT_SHARED_DEFAULTS)
    out["months"] = obj.default_months
    out["growth_pre_pct"] = obj.growth_pre_default
    out["growth_post_pct"] = obj.growth_post_default
    out.update(obj.defaults)
    # Поля гаража заводит признак гаража, а не память: у наземного паркинга
    # своего гаража нет вовсе, а доля гостевых — только там, где места
    # продаются (решение владельца 06.09.2026).
    if obj.garage:
        out["parking_under_spaces"] = 0
        out["parking_over_spaces"] = 0
        if obj.garage_sellable:
            out["parking_guest_pct"] = 10
            # Ноль означает «унаследовать общую цену подземного машино-места».
            # Поля раздельные: место на первом этаже не обязано стоить как
            # подземное. ТЦ и ФОК этих полей не получают — их места не продаются.
            out["parking_under_price_mln_per_space"] = 0
            out["parking_over_price_mln_per_space"] = 0
    if obj.sale_gate:
        out["disposition"] = "transfer"
    # Умолчание назначения — ПЕРВОЕ объявленное, а не литерал здесь: иначе
    # реестр и форма отвечали бы на «чем объект является по умолчанию» порознь.
    if obj.purposes:
        out["purpose"] = obj.purposes[0][0]
    out = {f"{obj.prefix}_{key}": value for key, value in out.items()}
    # Стратегия реализации — по умолчанию ДДУ: сохранённый проект без поля
    # считается так же, как считался.
    if obj.strategies:
        out.update(nonres_strategy.strategy_defaults(obj.prefix, obj.product))
        if not obj.garage_sellable:
            # Места ТЦ не продаются и не сдаются: они обеспечивают посетителей.
            out.pop(f"{obj.prefix}_parking_rent_th_month", None)
    return out


# Группа вводных объекта — та же форма, что и умолчания, только с подписями.
# Различаются группы ровно тем, что уже стоит в реестре: мера решает, чем
# объект меряется и по какой ставке считается, признак гаража — есть ли у него
# свои места, признак продаваемости — доля гостевых, признак выбора — строка
# «что с объектом дальше».
#
# Мера отвечает ЧЕТЫРЬМЯ местами формы, а не одним: у метров объём это GBA и
# продаваемая, себестоимость стоит после срока стройки, цена за метр, хвоста
# нет; у мест объём это число мест, себестоимость места идёт сразу за ним,
# цена за место, а в хвосте площадь на место для ТЭП. Перечислять их одним
