# Строки ТЭП объектов и их группы вводных приносит реестр: литерал держит
# только МЕСТО — порядок строк и порядок групп на экране, — а содержимое
# считается один раз.
#
# Заглушка называет ТИП: на её место встаёт тип и сразу за ним его экземпляры.
def _object_and_instances(placeholder: str) -> tuple[StandaloneObject, ...]:
    base = _BY_KEY[placeholder[len(_OBJECT_PLACEHOLDER):]]
    return tuple(o for o in STANDALONE_OBJECTS if o.key == base.key or o.family == base.key)


TEP_DEFAULT: dict[str, Any] = {
    _key: _value
    for _lkey, _row in _TEP_DEFAULT_LITERAL.items()
    for _key, _value in (
        ((o.key, standalone_object_tep_row(o)) for o in _object_and_instances(_row))
        if isinstance(_row, str) and _row.startswith(_OBJECT_PLACEHOLDER)
        else ((_lkey, _row),))
}

# Колонки строки ТЭП так, как их называет таблица ТЭП на странице. Окно
# импорта показывало вместо них ключи (`gns`, `saleable`) — человек видел
# схему, а не площади. Слова те же, что в шапке таблицы: одно имя колонки.
TEP_COLUMN_LABELS: dict[str, str] = {
    "gns": "ГНС, м²",
    "total_area": "Общая площадь, м²",
    "useful": "Полезная площадь, м²",
    "saleable": "Продаваемая площадь, м²",
    "transfer": "Передаваемая площадь, м²",
    "units": "Количество, шт.",
}

# Районы для поля «Район участка» — из таблицы приложения 3 к 1874-ПП
# (`mpt_calculator.ALL_DISTRICTS`), а не копией списка в литерале.
import mpt_calculator as _mpt_calculator
for _group in _FIELD_GROUPS_LITERAL:
    for _field in _group[1]:
        if len(_field) > 4 and _field[4] == 'MPT_DISTRICT_OPTIONS':
            _field[4] = [['', 'По разбору кадастра']] + [
                [name, name] for name in _mpt_calculator.ALL_DISTRICTS]

FIELD_GROUPS: list[Any] = [
    _item
    for _group in _FIELD_GROUPS_LITERAL
    for _item in (
        [standalone_object_group(o) for o in _object_and_instances(str(_group[0]))]
        if str(_group[0]).startswith(_OBJECT_PLACEHOLDER) else [_group])
]

# Группы и поля экземпляров: странице они не отдаются (см. `objectFields`).
_INSTANCE_GROUPS = frozenset(o.group_label for o in STANDALONE_OBJECTS if o.family)
# Группы вводных, которые рисует страница: всё, кроме групп экземпляров.
PAGE_FIELD_GROUPS: list[Any] = [group for group in FIELD_GROUPS
                                if group[0] not in _INSTANCE_GROUPS]
_INSTANCE_FIELDS = frozenset(
    field[0] for o in STANDALONE_OBJECTS if o.family for field in standalone_object_group(o)[1])

# Блок каждого поля объекта — для заголовков на странице. Отдельной картой, а не
# третьим элементом группы: группу и поле читают распаковкой в десятке мест.
FIELD_SECTIONS_PLACEHOLDER = "__DEVELOPAID_FIELD_SECTIONS__"
FIELD_SECTIONS: dict[str, str] = {
    field[0]: standalone_object_section(obj, field[0])
    for obj in STANDALONE_OBJECTS for field in standalone_object_group(obj)[1]
}


# Какие блоки формы объекта читает какая стратегия реализации. Блок, которого
# выбранная стратегия не читает, на странице не рисуется: поле, правка которого
# ничего не меняет, — не вводная. Значения при этом остаются в проекте.
STRATEGY_SECTION_READERS: dict[str, tuple[str, ...]] = {
    "Цена и рост цены": (nonres_strategy.STRATEGY_DDU, nonres_strategy.STRATEGY_DIRECT),
    "Темп продаж": (nonres_strategy.STRATEGY_DDU, nonres_strategy.STRATEGY_DIRECT),
    "Прямая продажа": (nonres_strategy.STRATEGY_DIRECT,),
    "Доходный метод": (nonres_strategy.STRATEGY_INCOME,),
    "Финансирование объекта": (nonres_strategy.STRATEGY_DIRECT,
                               nonres_strategy.STRATEGY_INCOME),
}


# Поля, которые читает не весь блок стратегий, а только часть. Схема погашения,
# срок и баллон — у доходного метода: при прямой продаже кредит гасится
# выручкой ДКП (проданное выходит из залога), и выбор «аннуитет» там ничего
# не менял — поле, правка которого ничего не меняет, не вводная.
STRATEGY_FIELD_READERS_BY_SUFFIX: dict[str, tuple[str, ...]] = {
    "debt_repayment": (nonres_strategy.STRATEGY_INCOME,),
    "loan_term_years": (nonres_strategy.STRATEGY_INCOME,),
    "loan_balloon_pct": (nonres_strategy.STRATEGY_INCOME,),
}


def strategy_field_readers() -> dict[str, list[Any]]:
    """Поле объекта → [его поле стратегии, стратегии, которые поле читают]."""
    out: dict[str, list[Any]] = {}
    for obj in STANDALONE_OBJECTS:
        if not obj.strategies:
            continue
        for field in standalone_object_group(obj)[1]:
            suffix = field[0].removeprefix(f"{obj.prefix}_")
            reads = (STRATEGY_FIELD_READERS_BY_SUFFIX.get(suffix)
                     or STRATEGY_SECTION_READERS.get(standalone_object_section(obj, field[0])))
            if reads:
                out[field[0]] = [f"{obj.prefix}_strategy", list(reads)]
    return out


# Правится в настройках класса, а не во «Вводных». МЕТОДИКА благоустройства —
# свойство класса ЦЕЛИКОМ, обеими половинами: норматив площади двора
# (11 / 15 / 20 м²/чел.) и ставка метра двора (15 / 35 / 50 тыс ₽/м²). Человек
# выбирает их выбором класса, а не набором чисел в форме.
#
# Половина методики уезжала сюда 14.09.2026, вторая осталась во «Вводных» — и
# это увидел владелец (15.09.2026): «во вводных оставалась стоимость на ГНС, а
# не расчёт, который мы оставили в настройках классов». Обе величины классовые,
# а жили по-разному: норматив скрыт, ставка видна. Во «Вводных» остаётся ОДНО
# число — счётный показатель на метр дома, полученный обратным счётом из этих
# двух (владелец, 14.09.2026: «во вводных счётный показатель руб на ГНС,
