# --- Рост цены после РВЭ: одна вводная ----------------------------------------
# Решение владельца (15.10.2026): видимая «Инфляция после РВЭ, % год» —
# единственный источник роста цены после РВЭ для движка, книги и отчётов.
# Раньше движок читал отдельное «Ежемесячный рост цены после РВЭ», а
# инфляция уходила только в шаблон ПЛАТО: правка видимого поля не меняла
# расчёт. Месячная ставка выводится отсюда, второй копии числа нет.
GROWTH_POST_LEGACY_KEY = "monthly_growth_post_pct"
# Прежнее умолчание поля: нетронутое, оно не решение человека и миграцией
# не переносится — действует видимая инфляция.
GROWTH_POST_LEGACY_DEFAULT = 0.25


def growth_post_monthly_pct(x: dict[str, Any]) -> float:
    """Рост цены после РВЭ, %/мес., из годовой «Инфляции после РВЭ»."""
    annual = n(x, "inflation_after_rve_pct", DEFAULT_INPUTS["inflation_after_rve_pct"])
    return ((1.0 + annual / 100.0) ** (1.0 / 12.0) - 1.0) * 100.0


def migrate_growth_post(x: dict[str, Any]) -> list[dict[str, Any]]:
    """Переносит прежнее месячное поле в годовую инфляцию. Правит `x`.

    Проект, сохранённый до решения, несёт `monthly_growth_post_pct`. Значение,
    отличное от прежнего умолчания или помеченное ручным, — решение человека:
    оно становится инфляцией (12 месяцев сложного роста), и происхождение
    подписано у поля. Нетронутое умолчание просто снимается. Возвращает
    список переносов — страница применяет его к своему состоянию.
    """
    if not isinstance(x, dict) or GROWTH_POST_LEGACY_KEY not in x:
        return []
    raw = x.pop(GROWTH_POST_LEGACY_KEY)
    origins = x.get("_field_origin") if isinstance(x.get("_field_origin"), dict) else None
    legacy_origin = (origins or {}).pop(f"inputs.{GROWTH_POST_LEGACY_KEY}", None)
    dropped = [{"from": GROWTH_POST_LEGACY_KEY, "key": None}]
    try:
        monthly = float(str(raw).replace(",", ".").strip())
    except (TypeError, ValueError):
        return dropped
    manual = isinstance(legacy_origin, dict) and legacy_origin.get("source") == "manual"
    if abs(monthly - GROWTH_POST_LEGACY_DEFAULT) < 1e-12 and not manual:
        return dropped
    annual = round(((1.0 + monthly / 100.0) ** 12 - 1.0) * 100.0, 6)
    text = ("пересчитано из прежнего поля «Ежемесячный рост цены после РВЭ» "
            + f"{monthly:g}".replace(".", ",") + "%/мес.")
    x["inflation_after_rve_pct"] = annual
    if origins is None:
        origins = {}
        x["_field_origin"] = origins
    origins["inputs.inflation_after_rve_pct"] = {"source": "migrated", "text": text}
    return [{"from": GROWTH_POST_LEGACY_KEY, "key": "inflation_after_rve_pct",
             "value": annual, "text": text}]
for _obj in STANDALONE_OBJECTS:
    DEFAULT_INPUTS.update(standalone_object_defaults(_obj))

# --- ФОК: объект уходит целиком одним путём ---------------------------------
# Решение владельца (05.09.2026): «Скорее нет, все или так или так». ФОК может
# и продаваться, и передаваться городу — но НЕ половиной метров сразу. Поэтому
# признак у объекта один, а не пара долей: доля попросила бы делить выручку и
# зачёт перед городом по одному объекту, и обе половины выглядели бы верными.
#
# Умолчание — передача. Отсутствующий ключ читается как «передаём», то есть
# как отсутствие выручки: потерянное поле не должно молча дорисовывать проекту
# продажи, которых человек не заказывал.
SPORTS_DISPOSITION_TRANSFER = "transfer"
SPORTS_DISPOSITION_SALE = "sale"


def object_is_sold(inputs: dict[str, Any] | None, obj: "StandaloneObject") -> bool:
    """Продаётся ли объект. Без признака — продаётся всегда.

    Признак (`sale_gate`) есть только у объекта, который может уйти городу;
    отсутствующее значение читается как передача — см. выше.
    """
    if not obj.sale_gate:
        return True
    value = str((inputs or {}).get(obj.sale_gate)
                or SPORTS_DISPOSITION_TRANSFER).strip().lower()
    return value == SPORTS_DISPOSITION_SALE


def sold_saleable_sqm(tep: dict[str, Any], inputs: dict[str, Any] | None) -> float:
    """Продаваемая площадь — то, что реально продаётся метрами.

    Квартиры, коммерция 1 этажа и объекты, продаваемые метрами (ОСЗ, офисы,
    ФОК — если он продаётся, а не уходит городу). Паркинг и кладовые продаются
    штуками, соцобъекты передаются — в метры продаж они не входят. Один ответ
    на «сколько метров продаём» для отчёта, тизера, первой страницы и бота:
    прежде отчёт не видел проданного ФОК, а тизер складывал колонку
    «Продаваемая» всех строк ТЭП, не спрашивая, продаётся ли строка.
    """
    keys = ["apartments", "ground_commercial"]
    for obj in STANDALONE_OBJECTS:
        if obj.measure != "sqm":
            continue
        if obj.sale_gate and not (b(inputs or {}, obj.enabled_key)
                                  and object_is_sold(inputs, obj)):
            continue
        keys.append(obj.key)
    # Объект продаёт остаток после мест первых этажей: строка ТЭП держит
    # площадь здания (владелец, 29.09.2026), ответ — `object_sold_saleable`.
    return sum(object_sold_saleable(inputs or {}, tep, key) if key in _BY_KEY
               else n(tep.get(key) or {}, "saleable") for key in keys)


# --- экземпляры объектов проекта ----------------------------------------------
# Какие экземпляры есть в проекте — явный список вводной `object_instances`
# (ключи реестра: `offices3`, `sports2`). Первый экземпляр типа (`offices`,
# `sports`) в проекте есть всегда — у него, как и прежде, свой выключатель.
#
# Отсутствующий ключ — не пустой список: проект, сохранённый до экземпляров
# (или присланный ботом, мостом, API), своего списка не несёт. Тогда состав
# берётся из того, что проект о себе сказал явно: включённые экземпляры, а у
# прежних «вторых» объектов (`LEGACY_SECOND_OBJECTS`) ещё и набранные метры —
# выключенный второй офисник с площадями оставался данными человека.
OBJECT_INSTANCES_KEY = "object_instances"
OBJECT_INSTANCES: dict[str, StandaloneObject] = {
    o.key: o for o in STANDALONE_OBJECTS if o.family}
# Прежние «вторые» объекты (#559): второй экземпляр каждого типа, у которого
# в шаблоне книги свой блок (офисы, ТЦ, наземный паркинг; у ФОКа блока нет).
LEGACY_SECOND_OBJECTS: tuple[str, ...] = tuple(
    object_instance(base, 2).key for base in OBJECT_TYPES if not base.book_twin)
_INSTANCE_VOLUME_FIELDS = ("gba_sqm", "saleable_sqm", "spaces",
                           "parking_under_spaces", "parking_over_spaces")


def _legacy_instance_has_data(inputs: dict[str, Any], obj: StandaloneObject) -> bool:
    defaults = standalone_object_defaults(obj)
    for field in _INSTANCE_VOLUME_FIELDS:
        key = f"{obj.prefix}_{field}"
        if key in inputs and key in defaults and n(inputs, key) != n(defaults, key):
            return True
    return False


def _instance_order(keys: Any) -> tuple[str, ...]:
    wanted = {str(key) for key in keys}
    return tuple(key for key in OBJECT_INSTANCES if key in wanted)


def project_object_instances(inputs: dict[str, Any] | None) -> tuple[str, ...]:
    """Экземпляры объектов, заведённые в проекте, — в порядке реестра."""
    x = inputs or {}
    raw = x.get(OBJECT_INSTANCES_KEY)
    if raw is None:
        return _instance_order(
            key for key, obj in OBJECT_INSTANCES.items()
            if b(x, obj.enabled_key)
            or (key in LEGACY_SECOND_OBJECTS and _legacy_instance_has_data(x, obj)))
    if isinstance(raw, str):
        raw = [part for part in re.split(r"[\s,;]+", raw) if part]
    return _instance_order(raw if isinstance(raw, (list, tuple, set, frozenset)) else ())


def project_objects(inputs: dict[str, Any] | None) -> tuple[StandaloneObject, ...]:
    """Объекты проекта: первые экземпляры типов и заведённые экземпляры."""
    present = set(project_object_instances(inputs))
    return tuple(o for o in STANDALONE_OBJECTS if not o.family or o.key in present)


def object_instance_notes(inputs: dict[str, Any] | None) -> list[str]:
    """Что из присланного про экземпляры расчёт НЕ принял — и почему."""
    x = inputs or {}
    raw = x.get(OBJECT_INSTANCES_KEY)
    if raw is None:
        return []
    if isinstance(raw, str):
        raw = [part for part in re.split(r"[\s,;]+", raw) if part]
    listed = [str(key) for key in raw] if isinstance(raw, (list, tuple, set, frozenset)) else []
    notes = [_unknown_instance_note(key)
             for key in listed if key not in OBJECT_INSTANCES and key not in _BY_KEY]
    present = set(project_object_instances(x))
    notes += [
        f"«{obj.group_label}» включён во вводных, но в составе проекта его нет — "
        "не считается"
        for key, obj in OBJECT_INSTANCES.items()
        if key not in present and b(x, obj.enabled_key)]
    return notes


def _unknown_instance_note(key: str) -> str:
    """Почему экземпляр из присланного списка не заведён.

    Тип узнаётся по явному списку типов, а не по разбору имени: ключ вида
    «тип + номер» проверяется против каждого недублируемого типа целиком.
    """
    for base in OBJECT_TYPES:
        if not base.duplicable and key in {f"{base.key}{number}" for number in range(2, 100)}:
            return (f"«{base.group_label}» не дублируется — объект «{key}» не "
                    "считается; его вводные сохранены как есть")
    return (f"объект «{key}» не заведён: такого экземпляра в реестре нет "
            f"(предел — {OBJECT_INSTANCES_MAX} объектов одного типа)")


def object_instance_refusal(inputs: dict[str, Any] | None, type_key: str) -> str:
    """Почему экземпляр типа добавить нельзя; пусто — можно."""
    base = _BY_KEY.get(type_key)
    if base is None or base.family:
        return f"типа объекта «{type_key}» нет"
    if not base.duplicable:
        return f"«{base.group_label}» не дублируется: в проекте он один"
    present = set(project_object_instances(inputs))
    free = [key for key, obj in OBJECT_INSTANCES.items()
            if obj.family == type_key and key not in present]
    if not free:
        return (f"«{base.group_label}»: в проекте уже {OBJECT_INSTANCES_MAX} "
                f"объектов этого типа — больше реестр не заводит "
                f"(OBJECT_INSTANCES_MAX)")
    return ""


def object_instance_add(inputs: dict[str, Any], type_key: str) -> str:
    """Заводит следующий свободный экземпляр типа; возвращает его ключ.

    Поля экземпляра встают умолчаниями его строки реестра — прежние значения
    удалённого экземпляра с тем же номером не воскресают. Предел — отказ с
    причиной (`object_instance_refusal`), а не молчаливая обрезка.
    """
    refusal = object_instance_refusal(inputs, type_key)
    if refusal:
        raise ValueError(refusal)
    present = project_object_instances(inputs)
    key = next(key for key, obj in OBJECT_INSTANCES.items()
               if obj.family == type_key and key not in present)
    inputs.update(standalone_object_defaults(OBJECT_INSTANCES[key]))
    inputs[OBJECT_INSTANCES[key].enabled_key] = True
    inputs[OBJECT_INSTANCES_KEY] = list(_instance_order((*present, key)))
    return key


def object_instance_remove(inputs: dict[str, Any], key: str) -> None:
    """Убирает экземпляр из проекта. Первый экземпляр типа не удаляется."""
    obj = OBJECT_INSTANCES.get(key)
    if obj is None:
        raise ValueError(f"«{key}» — не добавленный экземпляр объекта")
    present = project_object_instances(inputs)
    inputs[OBJECT_INSTANCES_KEY] = [item for item in present if item != key]
    inputs[obj.enabled_key] = False


def object_instances_applied(inputs: dict[str, Any],
                             tep: dict[str, dict[str, Any]]
                             ) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    """Вводные и ТЭП, которыми считает проект своего состава объектов.

    Экземпляр вне состава проекта не считается нигде: выключатель гасится,
    строка ТЭП — нули. Присланное не правится (копии), и список состава
    фиксируется явным — дальше по расчёту (очереди, книга) его не выводят
    заново. Проект без экземпляров возвращается теми же объектами.
    """
    present = project_object_instances(inputs)
    absent = [obj for key, obj in OBJECT_INSTANCES.items() if key not in present]
    if (inputs or {}).get(OBJECT_INSTANCES_KEY) == list(present) and not any(
            b(inputs, obj.enabled_key) for obj in absent):
        return inputs, tep
    x = dict(inputs or {})
    x[OBJECT_INSTANCES_KEY] = list(present)
    t = dict(tep or {})
    for obj in absent:
        if b(x, obj.enabled_key):
            x[obj.enabled_key] = False
        row = t.get(obj.key)
        if isinstance(row, dict) and any(
                n(row, col) for col in _RESIDENTIAL_EXCLUDED_TEP_COLUMNS):
            t[obj.key] = {**row, **{col: 0.0 for col in _RESIDENTIAL_EXCLUDED_TEP_COLUMNS
                                    if col in row}}
    return x, t


def sports_is_sold(inputs: dict[str, Any] | None) -> bool:
    """Продаётся ли ФОК. Всё остальное — передача городу."""
    return object_is_sold(inputs, next(o for o in STANDALONE_OBJECTS if o.key == "sports"))


# --- Тип проекта: что строим ------------------------------------------------
# Нежилой проект — офисный центр, торговля, ФОК, наземный паркинг и больше
# ничего: «режим расчёта нежилья, где нет ни КРТ ни ВРИ ничего» (владелец,
# 16.09.2026). Переключатель стоит в шапке рядом с классом, а НЕ у поля
# кадастра: кадастр отвечает на «где», а тип — на «что строим», и проект
# приезжает ещё файлом, ссылкой и мостом КРТ, минуя это поле вовсе.
#
# Финансирование режим не трогает — решение владельца того же дня: 214-ФЗ
# нежильё не исключает (ст. 1 ч. 1 — «иных объектов недвижимости», ст. 2 п. 2 —
# «жилое или нежилое помещение, машино-место»), значит эскроу, покрытие и
# лестница ставки ПФ остаются теми же, а оговорка «механика здесь не та» была
# бы неправдой на экране.
PROJECT_KIND_MIXED = "mixed"
PROJECT_KIND_NONRESIDENTIAL = "nonresidential"
# Гостиница — ОТДЕЛЬНЫЙ тип проекта, а не объект внутри жилого проекта или
# КРТ (владелец, 05.10.2026). Жилья, соцнагрузки и объектов у него нет, как у
# нежилого; деньги — номера, департаменты и USALI (`developaid_hotel_strategy`).
PROJECT_KIND_HOTEL = "hotel"
PROJECT_KINDS: tuple[tuple[str, str], ...] = (
    (PROJECT_KIND_MIXED, "Жильё"),
    (PROJECT_KIND_NONRESIDENTIAL, "Нежилое"),
    (PROJECT_KIND_HOTEL, "Гостиница"),
)
# Типы проекта без жилья. Один ответ на «считает ли проект дом»: нежилой и
# гостиничный обнуляют МКД и соцнагрузку одним и тем же правилом
# (`residential_excluded`), а называют остаток одной функцией
# (`nonresidential_leftovers`).
PROJECT_KINDS_WITHOUT_HOUSING = frozenset({PROJECT_KIND_NONRESIDENTIAL, PROJECT_KIND_HOTEL})

# Что принадлежит ЖИЛЬЮ и в нежилом проекте не живёт. Список объявлен один
# раз: по нему страница обнуляет и называет убранное, по нему же движок ищет
# оставшееся — два перечисления разошлись бы, и «режим включён» значило бы на
# экране одно, а в расчёте другое.
#
# Ставки и цены сюда не идут: они принадлежат классу, а на нулевых метрах
# ничего не считают. Нормативы соцобъекта (м² на место) — тоже: при нуле мест
# площадь из них не выходит.
NONRESIDENTIAL_CLEARED_INPUTS: dict[str, str] = {
    "kindergarten_places": "места ДОО",
    "school_places": "места СОШ",
    "clinic_capacity": "мощность поликлиники",
    "social_dou_gba_sqm": "площадь ДОО",
    "social_school_gba_sqm": "площадь СОШ",
    "social_clinic_gba_sqm": "площадь поликлиники",
    "social_compensation_mln": "соцкомпенсация",
    "land_rights_cost_mln": "плата за смену ВРИ",
    "underground_manual_spaces": "подземный паркинг проекта — места",
    "underground_manual_gns_sqm": "подземный паркинг проекта — площадь",
}

# Своей ставки двора у нежилого проекта НЕТ — решение владельца 21.09.2026:
# «не надо писать что ставка двора — это никому неинтересно и никакой роли не
# играет вообще! У нас себестоимость вообще всего объекта же целиком
# прописана» и следом «не считать». Двор входит в ставку СМР объекта, и
# отдельная статья была бы двойным счётом.
#
# Прежде режим ставил 10 тыс ₽/м² ГНС. Цена измерена на офиснике 19 110 м²:
# 210,7 млн ₽ CAPEX и LLCR 0,5427 против 0,5629 без неё.
#
# Поле `landscaping_gns_th_per_sqm` при этом остаётся и работает: заданная
# руками ставка сильнее методики в любом режиме — посчитать двор отдельно
# это решение человека, а не запрет методики.


def project_kind(inputs: dict[str, Any] | None) -> str:
    """Тип проекта. Незнакомое значение читается как жилой: умолчание годится
    там, где оно значит «не задано», а «не задано» здесь — это тот проект,
    который считался всегда."""
    value = str((inputs or {}).get("project_kind")
                or PROJECT_KIND_MIXED).strip().lower()
    return value if value in dict(PROJECT_KINDS) else PROJECT_KIND_MIXED


def is_nonresidential(inputs: dict[str, Any] | None) -> bool:
    """Нежилой ли проект (тип «Нежилое»: ТЦ, офисы, паркинг, ФОК)."""
    return project_kind(inputs) == PROJECT_KIND_NONRESIDENTIAL


def is_hotel(inputs: dict[str, Any] | None) -> bool:
    """Гостиничный ли проект."""
    return project_kind(inputs) == PROJECT_KIND_HOTEL


def without_housing(inputs: dict[str, Any] | None) -> bool:
    """Проект без жилья: нежилой или гостиничный. Решает, считается ли дом."""
    return project_kind(inputs) in PROJECT_KINDS_WITHOUT_HOUSING


# Ставки объектов, которые в чисто нежилом проекте значат СМР здания:
# метровые объекты (`object_rate_is_turnkey`). Ключ ставки → умолчание «под
# ключ» реестра.
OBJECT_SMR_RATE_DEFAULTS: dict[str, float] = {
    obj.rate_cost: float(obj.defaults.get("cost_th_per_sqm") or 0.0)
    for obj in STANDALONE_OBJECTS
    if not object_rate_is_turnkey({"project_kind": PROJECT_KIND_NONRESIDENTIAL}, obj)
}


def nonresidential_leftovers(inputs: dict[str, Any] | None,
                             tep: dict[str, Any] | None) -> list[str]:
    """Что осталось от жилья в нежилом проекте — поимённо.

    Сами не убираем: вводная принадлежит человеку, а не расчёту, а проект
    приходит файлом, ссылкой и мостом КРТ, страницы не проходя. Считать
    остаток расчёт не будет (`residential_excluded`), но и молчать нельзя:
    вводная, которой не видно в расчёте, читалась бы как потерянная.
    """
    if not without_housing(inputs):
        return []
    left: list[str] = []
    for key in MKD_PRODUCTS:
        row = (tep or {}).get(key) or {}
        area = max(n(row, "gns"), n(row, "total_area"),
                   n(row, "useful"), n(row, "saleable"))
        units = n(row, "units")
        if area <= 0 and units <= 0:
            continue
        label = str((TEP_DEFAULT.get(key) or {}).get("label") or key)
        # Разделитель разрядов меняется У ЧИСЛА, а не у всей фразы: применённый
        # к строке целиком, он съедает и запятые прозы.
        parts = []
        if area > 0:
            parts.append(f"{area:,.0f}".replace(",", " ") + " м²")
        if units > 0:
            parts.append(f"{units:,.0f}".replace(",", " ") + " шт.")
        left.append(f"{label}: " + ", ".join(parts))
    for key, label in NONRESIDENTIAL_CLEARED_INPUTS.items():
        value = n(inputs or {}, key)
        if value > 0:
            left.append(f"{label}: " + f"{value:,.0f}".replace(",", " "))
    # Гостиничный проект — одна гостиница: включённые ТЦ, офисы, паркинг и
    # ФОК в нём не считаются (`residential_excluded`), и это тоже остаток.
    if is_hotel(inputs):
        for obj in STANDALONE_OBJECTS:
            if b(inputs or {}, obj.enabled_key):
                left.append(f"{obj.group_label}: объект включён")
    return left


# Группы вводных, которые гостиничный проект читает: сроки, земля, стройка
# (ставки проекта, генподряд, резерв), налоги и финансирование (ставка
# дисконтирования). Продажи жилья, соцнагрузка, паркинги и объекты ему не
# принадлежат — вместо них блок «Гостиница» (`hotel_page_spec`).
HOTEL_PROJECT_GROUPS: tuple[str, ...] = (
    "Сделка и сроки", "Смена ВРИ и земельные права", "Строительство",
    "Коммерческие расходы и налоги", "Финансирование",
)


def hotel_page_spec() -> dict[str, Any]:
    """Блок «Гостиница» для страницы — из одного объявления полей.

    Поля, группы и варианты — `developaid_hotel_strategy.FIELDS`; ориентиры и
    их происхождение — `hotel_presets`; подсказка-диапазон пустого поля — по
    классу. Копии подписей на странице нет.
    """
    fields = []
    for f in hotel_strategy.FIELDS:
        hints = {}
        for stars in ("", *[c for c, _ in hotel_strategy.CLASSES]):
            hint = hotel_presets.hint_range(f.key, stars or None)
            if hint:
                hints[stars] = hint
        fields.append({
            "key": f.key, "label": f.label, "unit": f.unit, "group": f.group,
            "default": f.default, "origin": f.origin, "required": f.required,
            "kind": f.kind, "choices": [list(pair) for pair in f.choices],
            "hint": f.hint, "needed_when": list(f.needed_when) if f.needed_when else None,
            "capex": f.capex, "ranges": hints,
        })
    return {
        "fields": fields,
        "groups": [list(pair) for pair in hotel_strategy.GROUPS],
        "presets": hotel_presets.presets_for_page(),
        "preset_aliases": dict(hotel_presets.LEGACY_KEYS),
        "origins_key": hotel_presets.ORIGINS_KEY,
        "hidden_groups": [group[0] for group in FIELD_GROUPS
                          if group[0] not in HOTEL_PROJECT_GROUPS],
    }


def residential_excluded_rows(inputs: dict[str, Any] | None) -> frozenset[str]:
    """Строки ТЭП, которые проект объявленного типа не считает.

    Нежилой проект не считает дом (`MKD_PRODUCTS`) и соцобъекты (их строки
    идут от мест, а места — от населения). Строка остаётся в ответе движка с
    нулями и этим признаком: поверхность её не показывает, а ключ не
    пропадает у тех, кто ищет строку по имени.
    """
    if not without_housing(inputs):
        return frozenset()
    rows = frozenset(MKD_PRODUCTS) | frozenset(SOCIAL_TEP_FIELDS)
    if is_hotel(inputs):
        rows |= frozenset(obj.key for obj in STANDALONE_OBJECTS)
        rows |= frozenset(OBJECT_PARKING_PRODUCT_KEYS.values())
    return rows


# Количества строки ТЭП и строки продукта отчёта: строка вне состава
# скрывается, только пока все они пусты.
_ROW_QUANTITY_FIELDS: tuple[str, ...] = (
    "quantity", "revenue", "cost", "built_units")


def row_outside_project(inputs: dict[str, Any] | None, key: str,
                        row: dict[str, Any]) -> bool:
    """Строки ТЭП или продукта отчёта нет в составе проекта.

    Один ответ на «показывать ли строку» для всех таблиц, перечисляющих
    продукты и объекты: ТЭП и продажи отчёта страницы, PDF, Платон читают
    признак `excluded`, который ставит расчёт, а не выводят состав заново.
    Строки в ответе остаются — ключ не пропадает у тех, кто ищет строку по
    имени. Паркинг объекта (`OBJECT_PARKING_PRODUCT_KEYS`) — в составе вместе
    со своим объектом.

    Вне состава — то, что тип проекта не считает (`residential_excluded_rows`),
    и объект, которого в проекте нет: экземпляр не заведён
    (`project_objects`) или объект выключен. Строка объекта вне состава
    скрывается, только пока она пуста: выключенный объект с метрами в ТЭП
    итог по-прежнему складывает, и спрятать строку значило бы потерять из
    таблицы число, которое стоит в её итоге. Законный ноль продукта дома
    (передаётся 0) признаком не становится — он в составе.
    """
    if key in residential_excluded_rows(inputs):
        return True
    obj = _BY_KEY.get(key) or _BY_KEY.get(_OBJECT_OF_PARKING_PRODUCT.get(key, ""))
    if obj is None:
        return False
    x = inputs or {}
    if obj in project_objects(x) and b(x, obj.enabled_key):
        return False
    return not any(n(row, col) for col in (*_RESIDENTIAL_EXCLUDED_TEP_COLUMNS,
                                           *TEP_SUMMABLE_FIELDS,
                                           *_ROW_QUANTITY_FIELDS))


def row_listed(row: dict[str, Any]) -> bool:
    """Печатать ли строку ТЭП или продукта в списке продуктов проекта.

    Один ответ для тизера (модель представления) и таблицы ТЭП полного PDF.
    Строка есть, только если продукт есть в проекте: состав решает расчёт
    признаком `excluded` (`row_outside_project`), а продукт дома без метров и
    штук (кладовые 0) — не «ноль кладовых», а «кладовых нет». Объект, который
    заведён и включён, остаётся строкой и пустым: его в проекте завели.
    """
    if row.get("excluded"):
        return False
    if str(row.get("key") or "") in _BY_KEY:
        return True
    return any(n(row, col) for col in (*_RESIDENTIAL_EXCLUDED_TEP_COLUMNS,
                                       *TEP_SUMMABLE_FIELDS,
                                       *_ROW_QUANTITY_FIELDS))


# Столбцы строки ТЭП, которые несут количество: обнулив их, строка перестаёт
# участвовать в площадях, штуках, выручке и СМР. Подписи, признаки и нормативы
# строки не трогаются — это не количество.
_RESIDENTIAL_EXCLUDED_TEP_COLUMNS: tuple[str, ...] = (
    "gns", "total_area", "useful", "saleable", "transfer", "units",
    "guest_units", "transfer_units", "under_gns",
)


def residential_excluded(inputs: dict[str, Any],
                         tep: dict[str, dict[str, Any]]
                         ) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    """Вводные и ТЭП, которыми СЧИТАЕТ проект объявленного типа.

    Один предикат на вопрос «участвует ли жильё в расчёте»: у жилого проекта
    возвращаются те же объекты, у нежилого — копии, где продукты МКД
    (`MKD_PRODUCTS`: квартиры, встроенная коммерция, подземный паркинг МКД,
    кладовые) и жилые вводные (`NONRESIDENTIAL_CLEARED_INPUTS`: соцнагрузка,
    плата за ВРИ, пара «места ↔ площадь» паркинга МКД) обнулены.

    Сохранённое значение и участие в расчёте — разные вещи: присланное не
    правится, и возврат к жилому типу получает набранное назад. Прежде режим
    здесь только НАЗЫВАЛ остаток (`nonresidential_leftovers`), а расчёт его
    считал: на проекте владельца «Вавилов» (офисы 19 110 м²) строка МКД
    собиралась заново из оставшихся `underground_manual_*` — 149 мест,
    5 215 м² в строительном объёме, 834,6 млн ₽ выручки и СМР подземной части.
    """
    if not without_housing(inputs):
        return inputs, tep
    x = dict(inputs or {})
    for key in NONRESIDENTIAL_CLEARED_INPUTS:
        x[key] = 0
    if is_hotel(inputs):
        for obj in STANDALONE_OBJECTS:
            x[obj.enabled_key] = False
    # Признак ВРИ — не количество, и страница его не обнуляет; но платы за
    # смену ВРИ у нежилого проекта нет, и тизер по признаку писал строку
    # «Плата за смену ВРИ — 0 млн ₽», будто плата есть и равна нулю.
    x["vri_required"] = False
    # Копируются только строки МКД: строки объектов остаются теми же
    # объектами, и раскладка паркинга объекта (`apply_object_parking`) видна
    # вызывающему так же, как у жилого проекта.
    t = dict(tep or {})
    for key in MKD_PRODUCTS:
        row = t.get(key)
        if not isinstance(row, dict):
            continue
        row = dict(row)
        for col in _RESIDENTIAL_EXCLUDED_TEP_COLUMNS:
            if col in row:
                row[col] = 0.0
        t[key] = row
    # Гостиница — строка ТЭП своего проекта: её ГНС и есть ГНС
    # проекта, по нему считаются ГНС сводки и удельные. Только у гостиничного
    # проекта — у остальных строки нет вовсе, а не нулевой.
    if is_hotel(inputs):
        gns = n(x, "hotel_gba_sqm")
        t[HOTEL_TEP_KEY] = {"label": "Гостиница", "gns": gns, "total_area": 0.0,
                            "useful": 0.0, "saleable": 0.0, "transfer": 0.0, "units": 0.0}
    return x, t


