class CalcRequest(BaseModel):
    inputs: dict[str, Any]
    tep: dict[str, dict[str, Any]]
    rates: list[dict[str, Any]] = []
    # Сессия входа: ею же считается учёт и открывается расчёт экономики
    # (решение владельца, 18.08.2026 — «счёт виден, вывод за входом»).
    session: str = ""
    access_key: str = ""
    # Факт действующего проекта: дата среза и помесячные ряды до неё. Пусто —
    # проект считается с нуля, как считался всегда. Задано — ряды до среза
    # подменяются фактическими, а плановый хвост перенормируется на остаток
    # (`developaid_actuals.overlay`).
    actuals: dict[str, Any] = {}


class PhasedCalcRequest(BaseModel):
    inputs: dict[str, Any]
    tep: dict[str, dict[str, Any]]
    rates: list[dict[str, Any]] = []
    phasing: dict[str, Any] = {}
    session: str = ""
    access_key: str = ""


class SensitivityRequest(BaseModel):
    inputs: dict[str, Any]
    tep: dict[str, dict[str, Any]]
    rates: list[dict[str, Any]] = []
    phasing: dict[str, Any] = {}
    metric: str = "llcr"
    # Пусто — выбирается сам: весь проект, а у многоочередного — слабейшая очередь.
    scope: str = ""
    selected_view: str = "all"
    # Пусто — все применимые параметры.
    parameters: list[str] = []
    change_pct: float = 10.0
    duration_change_months: float = 6.0
    # Чувствительность — тот же расчёт, только многократный: за входом и правом
    # на участок (`require_calc_access`).
    session: str = ""
    access_key: str = ""


class AgentDocumentRequest(BaseModel):
    """Присланный документ по участку: тизер, справка, решение ГЗК.

    Файл приходит base64 в теле, а не формой: тем же путём, что и остальные
    запросы страницы, и без второго способа авторизации.
    """
    filename: str = ""
    content_b64: str = ""
    inputs: dict[str, Any] = {}
    tep: dict[str, dict[str, Any]] = {}
    session: str = ""
    access_key: str = ""
    # Ключи, которые человек подтвердил в таблице разбора. Пусто — только
    # показать: применение это отдельное действие, а не следствие загрузки.
    accept: list[str] = []
    extraction: dict[str, Any] = {}


class AgentDocumentAnswerRequest(BaseModel):
    """Ответ на один вопрос по документу из очереди на диске.

    `index` — номер вопроса, на который отвечают: окно и очередь сверяют его,
    и двойное нажатие или вторая вкладка не отвечают за соседний вопрос.
    """
    intake_id: str
    index: int
    action: str = "answer"  # answer | skip | stop
    choice: int = -1
    value: str = ""
    # Поле обязательства уже несёт своё число: «add» — прибавить ответ к
    # нему, «replace» — заменить. Пусто — сервер сначала спросит.
    mode: str = ""
    inputs: dict[str, Any] = {}
    tep: dict[str, dict[str, Any]] = {}
    session: str = ""
    access_key: str = ""


class AgentChatRequest(BaseModel):
    message: str
    inputs: dict[str, Any]
    tep: dict[str, dict[str, Any]]
    rates: list[dict[str, Any]] = []
    phasing: dict[str, Any] = {}
    history: list[dict[str, Any]] = []
    # Документ, присланный на разбор, — в разговоре до следующей загрузки
    # (`document_intake.chat_context`). Отдельно от истории: история режется
    # по числу реплик, и документ выпадал бы из неё через три вопроса.
    document: dict[str, Any] = {}
    selected_view: str = "all"
    # Сценарий кнопки: известный id считается движком без вызова модели.
    scenario: str = ""
    # Идентификатор запроса генерирует страница: он нужен ей раньше ответа,
    # чтобы опрашивать стадию, пока запрос идёт.
    trace_id: str = ""
    # Кто спрашивает: подписанная телеграм-сессия (мини-приложение или вход
    # через бота) либо ключ администратора. Платон стоит денег на каждый
    # вопрос, поэтому с сайта он доступен после входа.
    session: str = ""
    access_key: str = ""


class CadastralAnalysisRequest(BaseModel):
    cadastral_numbers: str | list[str]
    # Идентификатор запуска со страницы: по нему в журнале сшиваются старт,
    # ответ и применение одного клика «Получить ТЭП».
    request_id: str = ""
    # Территория, уже собранная страницей перед этим запросом. Серверный расчёт
    # ТЭП спрашивал её у ГлавАПУ второй раз за тот же клик — лишний внешний
    # запрос в цепочке, которая и без него небыстрая. Присланная территория
    # принимается, только если это территория запрошенных участков.
    cadastral_analysis: dict[str, Any] | None = None


class CadastralTepRequest(BaseModel):
    rows: list[dict[str, Any]]
    cadastral_analysis: dict[str, Any] | None = None


